import '@servicenow/sdk/global'
import { Flow, wfa, action, trigger } from '@servicenow/sdk/automation'

// Nested forEach test - verify each loop gets distinct UUID prefix
Flow(
    {
        $id: Now.ID['foreach_datapill_nested_test'],
        name: 'ForEach Data Pill Nested Test',
        description: 'Test that nested forEach loops have distinct UUID prefixes',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['foreach_nested_trigger'] },
        {
            table: 'problem',
            condition: '',
            run_on_extended: 'false',
            run_flow_in: 'background',
            run_when_user_list: [],
            run_when_setting: 'both',
            run_when_user_setting: 'any',
        }
    ),
    (_params) => {
        const problems = wfa.action(
            action.core.lookUpRecords,
            {
                $id: Now.ID['lookup_problems_outer'],
                annotation: 'Find problem records',
            },
            {
                table: 'problem',
                conditions: 'active=true',
            }
        )

        const incidents = wfa.action(
            action.core.lookUpRecords,
            {
                $id: Now.ID['lookup_incidents'],
                annotation: 'Find incident records',
            },
            {
                table: 'incident',
                conditions: 'active=true',
            }
        )

        // Outer forEach
        wfa.flowLogic.forEach(
            wfa.dataPill(problems.Records, 'array.object'),
            { $id: Now.ID['foreach_problems_outer'], annotation: 'Iterate each problem' },
            (problem) => {
                wfa.action(
                    action.core.log,
                    {
                        $id: Now.ID['log_outer'],
                        annotation: 'Log outer problem',
                    },
                    {
                        log_level: 'info',
                        log_message: `Outer Problem: ${wfa.dataPill(problem.number, 'string')}`,
                    }
                )

                // Inner forEach
                wfa.flowLogic.forEach(
                    wfa.dataPill(incidents.Records, 'array.object'),
                    { $id: Now.ID['foreach_incidents_inner'], annotation: 'Iterate each incident' },
                    (incident) => {
                        wfa.action(
                            action.core.log,
                            {
                                $id: Now.ID['log_inner'],
                                annotation: 'Log both problem and incident',
                            },
                            {
                                log_level: 'info',
                                log_message: `Problem: ${wfa.dataPill(problem.number, 'string')}, Incident: ${wfa.dataPill(incident.number, 'string')}`,
                            }
                        )
                    }
                )
            }
        )
    }
)
